import heapq

def min_schools_to_make_up(n, m, k, powers, schools, chosen_ones):
    # Create a dictionary to store the strongest student in each school
    strongest_students = {i: None for i in range(1, m + 1)}

    # Populate the dictionary with the initial strongest students
    for i in range(n):
        if strongest_students[schools[i]] is None or powers[i] > powers[strongest_students[schools[i]] - 1]:
            strongest_students[schools[i]] = i + 1

    # Create a set to keep track of schools that need replacement
    schools_to_replace = set()

    # Iterate over the chosen ones and check if they are the strongest in their school
    for co in chosen_ones:
        if strongest_students[schools[co - 1]] != co:
            schools_to_replace.add(schools[co - 1])

    # Create a priority queue to find the next strongest student for each school
    pq = []
    for i in range(1, m + 1):
        if strongest_students[i] is not None:
            heapq.heappush(pq, (-powers[strongest_students[i] - 1], i))

    # Replace the weakest student in each school that needs it
    while len(schools_to_replace) > 0:
        _, school = heapq.heappop(pq)
        if school in schools_to_replace:
            schools_to_replace.remove(school)
            if len(pq) > 0:
                next_strongest_power, _ = pq[0]
                next_strongest_index = strongest_students[_] - 1
                if next_strongest_power < -powers[next_strongest_index]:
                    strongest_students[_] = next_strongest_index + 1
                    heapq.heapreplace(pq, (-powers[next_strongest_index], _))

    return len(schools_to_replace)

# Example usage:
